package com.student.controller;
import com.student.dao.StudentDAO; import com.student.model.Student; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class RegisterServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String fn=req.getParameter("firstName"),ln=req.getParameter("lastName"),email=req.getParameter("email");if(fn==null||fn.isBlank()||ln==null||ln.isBlank()||email==null||email.isBlank())throw new IllegalArgumentException();Student s=new Student();s.setFirstName(fn);s.setLastName(ln);s.setEmail(email);s.setPhone(req.getParameter("phone"));s.setGender(req.getParameter("gender"));s.setDepartment(req.getParameter("department"));s.setCity(req.getParameter("city"));s.setCourseId(Integer.parseInt(req.getParameter("courseId")));s.setStatus("ACTIVE");new StudentDAO().save(s);resp.sendRedirect("registration-success");}catch(Exception e){req.setAttribute("error","Please complete the required fields correctly.");try{req.setAttribute("courses",new com.student.dao.CourseDAO().findActiveCourses());}catch(Exception ignored){}req.getRequestDispatcher("/registration.jsp").forward(req,resp);}}}
